package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.ByteBuffer;
import java.nio.channels.ClosedChannelException;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate1Test {

  @Test
  void readBehaviors() throws Exception {
    byte[] data = {1, 2, 3, 4, 5};
    ByteArraySeekableByteChannel ch = new ByteArraySeekableByteChannel(data);

    // Partial read limited by destination capacity
    ByteBuffer small = ByteBuffer.allocate(2);
    assertEquals(2, ch.read(small));
    assertArrayEquals(new byte[] {1, 2}, small.array());
    assertEquals(2, ch.position());

    // Destination larger than remaining data: only remaining bytes are read
    ByteBuffer big = ByteBuffer.allocate(10);
    assertEquals(3, ch.read(big));
    assertEquals(3, big.position());
    assertEquals(7, big.remaining());
    assertArrayEquals(new byte[] {3, 4, 5, 0, 0, 0, 0, 0, 0, 0}, big.array());
    assertEquals(5, ch.position());

    // At end of data returns -1 and leaves position unchanged
    ByteBuffer eof = ByteBuffer.allocate(4);
    assertEquals(-1, ch.read(eof));
    assertEquals(0, eof.position());
    assertEquals(5, ch.position());

    // Zero-remaining destination in the middle returns 0 and doesn't move position
    ch.position(1);
    ByteBuffer empty = ByteBuffer.allocate(0);
    assertEquals(0, ch.read(empty));
    assertEquals(1, ch.position());

    // Respects the destination's current position offset
    ByteBuffer offset = ByteBuffer.allocate(5);
    offset.position(3);
    assertEquals(2, ch.read(offset));
    assertArrayEquals(new byte[] {0, 0, 0, 2, 3}, offset.array());
    assertEquals(3, ch.position());

    // Null data behaves as empty
    ByteArraySeekableByteChannel nullCh = new ByteArraySeekableByteChannel(null);
    assertEquals(-1, nullCh.read(ByteBuffer.allocate(1)));

    // Closed channel throws
    ch.close();
    assertThrows(ClosedChannelException.class, () -> ch.read(ByteBuffer.allocate(1)));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.ByteBuffer;
import java.nio.channels.ClosedChannelException;
import java.nio.channels.SeekableByteChannel;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate2Test {

  @Test
  void positionBehavior() throws Exception {
    byte[] data = {10, 20, 30, 40, 50};
    ByteArraySeekableByteChannel ch = new ByteArraySeekableByteChannel(data);

    // Returns this and sets position
    SeekableByteChannel returned = ch.position(2);
    assertSame(ch, returned);
    assertEquals(2L, ch.position());

    // Reading starts at the new position
    ByteBuffer buf = ByteBuffer.allocate(10);
    assertEquals(3, ch.read(buf));
    assertEquals(30, buf.get(0));
    assertEquals(40, buf.get(1));
    assertEquals(50, buf.get(2));
    assertEquals(5L, ch.position());

    // Position zero is valid (boundary)
    ch.position(0);
    assertEquals(0L, ch.position());

    // Position beyond size is allowed; read returns -1
    ch.position(100);
    assertEquals(100L, ch.position());
    assertEquals(-1, ch.read(ByteBuffer.allocate(4)));

    // Max int is accepted
    ch.position(Integer.MAX_VALUE);
    assertEquals((long) Integer.MAX_VALUE, ch.position());

    // Invalid positions throw and leave position unchanged
    ch.position(3);
    assertThrows(IllegalArgumentException.class, () -> ch.position(-1));
    assertEquals(3L, ch.position());
    assertThrows(IllegalArgumentException.class, () -> ch.position((long) Integer.MAX_VALUE + 1));
    assertEquals(3L, ch.position());

    // Closed channel throws ClosedChannelException, even for invalid position
    ch.close();
    assertThrows(ClosedChannelException.class, () -> ch.position(1));
    assertThrows(ClosedChannelException.class, () -> ch.position(-1));
  }
}

package io.github.iachimoe.tarballfs;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

import java.nio.ByteBuffer;
import java.nio.channels.NonWritableChannelException;
import org.junit.jupiter.api.Test;

class ByteArraySeekableByteChannelMutaGate3Test {

  @Test
  void writeThrowsNonWritableAndLeavesStateUnchanged() throws Exception {
    byte[] data = {1, 2, 3, 4};
    ByteArraySeekableByteChannel channel = new ByteArraySeekableByteChannel(data);
    ByteBuffer src = ByteBuffer.wrap(new byte[] {9, 9});

    assertThrows(NonWritableChannelException.class, () -> channel.write(src));

    assertEquals(2, src.remaining());
    assertEquals(0, src.position());
    assertEquals(0L, channel.position());
    assertEquals(4L, channel.size());
    assertEquals(true, channel.isOpen());

    ByteBuffer dst = ByteBuffer.allocate(4);
    assertEquals(4, channel.read(dst));
    assertEquals(1, dst.get(0));
    assertEquals(2, dst.get(1));
    assertEquals(3, dst.get(2));
    assertEquals(4, dst.get(3));

    channel.close();
    assertThrows(NonWritableChannelException.class, () -> channel.write(ByteBuffer.allocate(1)));
  }
}

